let currentLang = SSLS.getItem('ch_lang') || 'en';
function t(key, vars){
  let str = (I18N[currentLang] && I18N[currentLang][key]) || I18N.en[key] || key;
  if(vars) Object.keys(vars).forEach(k=>{ str = str.replace('{'+k+'}', vars[k]); });
  return str;
}
function setLang(lang){ currentLang = lang; SSLS.setItem('ch_lang', lang); applyI18n(); }
function applyI18n(){
  document.getElementById('langSel').value = currentLang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{ el.innerHTML = t(el.getAttribute('data-i18n')); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{ el.placeholder = t(el.getAttribute('data-i18n-ph')); });
}

